/* @lc app=leetcode id=3690 lang=kotlin */ class Solution { fun nb(a: List<Int>): List<List<Int>> = a.indices.flatMap { l -> (l until a.size).flatMap { r -> (a.take(l) + a.drop(r + 1)).let { rest -> (0..rest.size).map { p -> rest.take(p) + a.subList(l, r + 1) + rest.drop(p) } } } } fun minSplitMerge(nums1: IntArray, nums2: IntArray): Int = HashSet<List<Int>>().also { it.add(nums1.toList()) }.let { vis -> generateSequence(listOf(nums1.toList()) to 0) { (f, d) -> if (nums2.toList() in f) null else f.flatMap { nb(it) }.filter { vis.add(it) }.takeIf { it.isNotEmpty() }?.let { it to d + 1 } }.last().second } }